function addlOrder(){const l=seedAddl(),c=l[SAD.i];const ok=c.paid||/explain|reason|reconcil|differ/i.test((c.replies[0]||{}).t||'');c.orders.push({f:/ASMT/.test(c.type)?(ok?'ASMT-12 (reply found satisfactory - proceedings dropped)':'Proceedings initiated u/s 73 (DRC-01)'):(ok?'DRC-01A Part B accepted - proceedings concluded':'Show cause notice DRC-01 issued'),d:today(),r:ok?'Closed':'Further action'});c.st=ok?'Closed':'Order issued';put('addl',l);SAD.tab=2;show('View Additional Notices / Orders')}
V['Holiday List']=()=>{const y=new Date(today()).getFullYear(),st=window._hs||U.state;const H5=[[`${y}-01-26`,'Republic Day','National'],[`${y}-08-15`,'Independence Day','National'],[`${y}-10-02`,'Gandhi Jayanti','National'],[`${y}-05-01`,'State day / Labour day (practice)','State'],[`${y}-12-25`,'Christmas','State']];
return card('Holiday List',`<div class="row"><div><label>State *</label><select id="hl_s" onchange="window._hs=this.value;show('Holiday List')">${Object.entries(STATES).map(([c,n])=>`<option value="${c}" ${c===st?'selected':''}>${c}-${n}</option>`).join('')}</select></div><div><label>Year</label><input value="${y}" disabled></div></div><table class="grid1" id="holT"><tr><th>Date</th><th>Day</th><th>Holiday</th><th>Type</th></tr>${H5.sort().map(([d,n,t])=>`<tr><td>${d}</td><td>${new Date(d).toLocaleDateString('en-IN',{weekday:'long'})}</td><td>${n}</td><td>${t}</td></tr>`).join('')}</table><div class="note">Practice list for ${STATES[st]}. If a due date falls on a holiday, check the official state notification - due dates are not automatically extended unless notified.</div>`,'services')};
V['Feedback']=()=>{const l=get('fb',[]);return card('Feedback',`<div class="row"><div><label>Module *</label><select id="fb_m"><option>Registration</option><option>Returns</option><option>Payments</option><option>Refunds</option><option>User Services</option></select></div><div><label>Rating *</label><select id="fb_r"><option>5 - Excellent</option><option>4 - Good</option><option>3 - Average</option><option>2 - Poor</option><option>1 - Very poor</option></select></div></div><label>Comments</label><textarea id="fb_c" rows="3" style="width:100%"></textarea><button class="btn s" id="fb_go" onclick="const l=get('fb',[]);l.unshift({d:today(),m:$('fb_m').value,r:$('fb_r').value,c:$('fb_c').value});put('fb',l);alert('Thank you for your feedback.');show('Feedback')">SUBMIT</button><h4>Your feedback</h4><table><tr><th>Date</th><th>Module</th><th>Rating</th><th>Comments</th></tr>${l.map(x=>`<tr><td>${x.d}</td><td>${x.m}</td><td>${x.r}</td><td>${esc(x.c)}</td></tr>`).join('')||'<tr><td colspan=4>None</td></tr>'}</table>`,'services')};
function gstps(){const R=sr5('gstp'),N=['Mehra','Iyer','Khan','Patel','Das','Reddy','Singh','Joshi','Nair','Gupta','Rao','Shah'],o=[];Object.keys(STATES).slice(0,40).forEach(st=>{for(let i=0;i<3;i++){const n=N[Math.floor(R()*N.length)];o.push({id:st+'2'+String(Math.floor(R()*1e9)).padStart(9,'0')+'TRP',name:['A','R','S','K','P'][i]+'. '+n+' (practice GSTP)',st,dist:['Central','North','South'][i],mob:'9'+String(Math.floor(R()*1e9)).padStart(9,'0').slice(0,4)+'XXXXX',email:n.toLowerCase()+i+'@example.com'})}});return o}
V['Locate GST Practitioner (GSTP)']=()=>{const q=window._gq||{st:U.state,n:''},l=gstps().filter(g=>g.st===q.st&&(!q.n||g.name.toLowerCase().includes(q.n.toLowerCase())));return card('Locate GST Practitioner (GSTP)',`<div class="row"><div><label>State *</label><select id="gq_s">${Object.entries(STATES).map(([c,n])=>`<option value="${c}" ${c===q.st?'selected':''}>${n}</option>`).join('')}</select></div><div><label>Name (optional)</label><input id="gq_n" value="${esc(q.n)}"></div><div style="align-self:end"><button class="btn s" onclick="window._gq={st:$('gq_s').value,n:$('gq_n').value};show('Locate GST Practitioner (GSTP)')">SEARCH</button></div></div><table class="grid1" id="gstpT"><tr><th>Enrolment ID</th><th>Name</th><th>District</th><th>Mobile</th><th>Email</th></tr>${l.map(g=>`<tr><td>${g.id}</td><td>${g.name}</td><td>${g.dist}</td><td>${g.mob}</td><td>${g.email}</td></tr>`).join('')||'<tr><td colspan=5>No GSTP found</td></tr>'}</table><div class="note">Fictional practitioners for practice. Use the enrolment ID in <b>Engage / Disengage GST Practitioner</b>.</div>`,'services')};
V['Engage / Disengage GST Practitioner (GSTP)']=()=>{const e=get('gstp',[]);return card('Engage / Disengage GST Practitioner (GSTP)',`<div class="row"><div><label>Enrolment ID of GSTP *</label><input id="gp_id" placeholder="e.g. from Locate GSTP" oninput="this.value=this.value.toUpperCase()"></div><div style="align-self:end"><button class="btn" onclick="const g=gstps().find(x=>x.id===$('gp_id').value);$('gp_nm').textContent=g?g.name+' ('+STATES[g.st]+')':'No GSTP found with this enrolment ID'">SEARCH</button></div></div><p id="gp_nm"></p>
<label>Authorise for *</label><div class="inline chk">${['GSTR-1/IFF','GSTR-3B','GSTR-9','Refund','Registration amendment','Payment (challan)'].map(x=>`<label><input type="checkbox" class="gpa" value="${x}" checked> ${x}</label>`).join('')}</div><button class="btn s" id="gp_go" onclick="gstpEngage()">ENGAGE</button>
<h4>Engaged practitioners</h4><table class="grid1" id="gpT"><tr><th>Enrolment ID</th><th>Name</th><th>Engaged on</th><th>Authorised for</th><th>Status</th><th>Action</th></tr>${e.map((g,i)=>`<tr><td>${g.id}</td><td>${g.name}</td><td>${g.d}</td><td>${g.a.join(', ')}</td><td>${g.st}</td><td>${g.st==='Engaged'?`<button class="btn sm del" onclick="gstpDis(${i})">DISENGAGE</button>`:'-'}</td></tr>`).join('')||'<tr><td colspan=6>No GSTP engaged</td></tr>'}</table><div class="note">A taxpayer may engage one or more GSTPs. The GSTP can prepare returns; the taxpayer must still confirm/submit and file (EVC/DSC). Disengage any time.</div>`,'services')};
function gstpEngage(){const g=gstps().find(x=>x.id===$('gp_id').value.trim());if(!g)return alert('Enter a valid GSTP enrolment ID (see Locate GST Practitioner)');const e=get('gstp',[]);if(e.some(x=>x.id===g.id&&x.st==='Engaged'))return alert('This GSTP is already engaged');const a=[...document.querySelectorAll('.gpa:checked')].map(c=>c.value);if(!a.length)return alert('Select at least one authority');e.unshift({id:g.id,name:g.name,d:today(),a,st:'Engaged'});put('gstp',e);alert('GSTP engaged successfully. Intimation sent to the GSTP (practice).');show('Engage / Disengage GST Practitioner (GSTP)')}
function gstpDis(i){if(!confirm('Disengage this GSTP?'))return;const e=get('gstp',[]);e[i].st='Disengaged on '+today();put('gstp',e);show('Engage / Disengage GST Practitioner (GSTP)')}
V['Contacts']=()=>{const l=get('contacts',[]);return card('Contacts',`<div class="note">Save contact details of customers/suppliers (used when you prepare invoices and returns).</div><div class="row"><div><label>Name *</label><input id="ct_n"></div><div><label>GSTIN</label><input id="ct_g" oninput="this.value=this.value.toUpperCase()"></div><div><label>Mobile</label><input id="ct_m" maxlength="10"></div><div><label>Email</label><input id="ct_e"></div><div style="align-self:end"><button class="btn s" id="ct_go" onclick="ctAdd()">ADD</button></div></div><table class="grid1" id="ctT"><tr><th>Name</th><th>GSTIN</th><th>Mobile</th><th>Email</th><th>Action</th></tr>${l.map((c,i)=>`<tr><td>${esc(c.n)}</td><td>${c.g}</td><td>${c.m}</td><td>${esc(c.e)}</td><td><button class="btn sm del" onclick="const l=get('contacts',[]);l.splice(${i},1);put('contacts',l);show('Contacts')">DELETE</button></td></tr>`).join('')||'<tr><td colspan=5>No contacts</td></tr>'}</table>`,'services')};
function ctAdd(){const n=$('ct_n').value.trim(),g=$('ct_g').value.trim(),m=$('ct_m').value.trim(),e=$('ct_e').value.trim();if(!n)return alert('Name is required');if(g&&!validGSTIN(g))return alert('Invalid GSTIN');if(m&&!/^[6-9]\d{9}$/.test(m))return alert('Mobile must be 10 digits starting 6-9');if(e&&!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(e))return alert('Invalid email');const l=get('contacts',[]);l.push({n,g,m,e});put('contacts',l);show('Contacts')}
/* ---------- ITC Forms (ITC-01, 02, 02A, 03; ITC-04 link) ---------- */
const ITCF={'ITC-01':'Declaration for claim of ITC u/s 18(1) (new / voluntary registration, exit from composition, exempt to taxable)','ITC-02':'Transfer of ITC on sale, merger, demerger, amalgamation, lease or transfer of business (Rule 41)','ITC-02A':'Transfer of ITC to a new registration of the same PAN in the same State (Rule 41A)','ITC-03':'Reversal of ITC on stock on opting composition / supplies becoming wholly exempt (Sec 18(4), Rule 44)'};
V['ITC Forms']=()=>card('ITC Forms',`<div class="rtiles r3">${Object.entries(ITCF).map(([k,v])=>`<div class="rtile" id="itc_${k.replace('-','')}" onclick="itcOpen('${k}')"><b>${k}</b><span>${v}</span></div>`).join('')}<div class="rtile" onclick="show('ITC-04 (Job Work)')"><b>ITC-04</b><span>Details of goods sent to / received from job worker</span></div></div><div id="itcF"></div>`+appsTable('itc')+`<div id="itcPend"></div>`,'services');
const itcRows=()=>[...document.querySelectorAll('#itcRows tr.ir')].map(r=>{const g=c=>r.querySelector('.'+c).value;return {desc:g('i_d'),no:g('i_n'),date:g('i_dt'),val:+g('i_v')||0,igst:+g('i_ig')||0,cgst:+g('i_cg')||0,sgst:+g('i_sg')||0,cess:+g('i_cs')||0}});
const irw=(r={})=>`<tr class="ir"><td><input class="i_d" value="${esc(r.desc||'Stock of inputs')}"></td><td><input class="i_n" value="${esc(r.no||'')}"></td><td><input type="date" class="i_dt" value="${r.date||''}"></td><td><input type="number" class="i_v" value="${r.val||''}"></td>${['ig','cg','sg','cs'].map((c,i)=>`<td><input type="number" class="i_${c}" value="${r[H[i]]||0}" style="width:90px"></td>`).join('')}</tr>`;
function itcOpen(k,si){const sv=si!=null?(get('saved',[])[si]||{}).data||{}:{};const bal=credBal();let h=`<div class="card"><h4>Form GST ${k} - ${ITCF[k]}</h4>`;
if(k==='ITC-01')h+=`<div class="row"><div><label>Claim under *</label><select id="i1_c"><option value="a">18(1)(a) - New registration (applied within 30 days)</option><option value="b">18(1)(b) - Voluntary registration</option><option value="c">18(1)(c) - Opting out of composition</option><option value="d">18(1)(d) - Exempt supply becoming taxable</option></select></div><div><label>Date from which liability to pay tax arises / eligible *</label><input type="date" id="i1_dt"></div></div>`;
if(k==='ITC-02'||k==='ITC-02A')h+=`<div class="row"><div><label>GSTIN of transferee *</label><input id="i2_g" oninput="this.value=this.value.toUpperCase()"></div>${k==='ITC-02'?`<div><label>Particulars of change *</label><select id="i2_r"><option>Sale</option><option>Merger</option><option>Demerger</option><option>Amalgamation</option><option>Lease</option><option>Transfer of business</option></select></div>`:`<div><label>Date of new registration *</label><input type="date" id="i2_dt"></div>`}</div><p>Credit ledger balance available: ${H.map(h=>HN[h]+' ₹'+f(bal[h])).join(', ')}</p><div class="row">${H.map(h=>`<div><label>${HN[h]} to transfer (₹)</label><input type="number" id="i2_${h}" value="0"></div>`).join('')}</div>`;
if(k==='ITC-03')h+=`<div class="row"><div><label>Reason *</label><select id="i3_r"><option>Opted for composition (Sec 10)</option><option>Supplies became wholly exempt</option></select></div><div><label>Date of event *</label><input type="date" id="i3_dt"></div></div>`;
if(k==='ITC-01'||k==='ITC-03')h+=`<h4>${k==='ITC-01'?'Details of inputs held in stock / capital goods (invoice-wise)':'ITC on inputs held in stock, semi-finished / finished goods and capital goods to be reversed'}</h4><table class="itm" id="itcRows"><tr><th>Description</th><th>Invoice No.</th><th>Invoice date</th><th>Value (₹)</th>${H.map(h=>`<th>${HN[h]} (₹)</th>`).join('')}</tr>${(sv.rows&&sv.rows.length?sv.rows:[{}]).map(irw).join('')}</table><button class="btn sm" onclick="document.getElementById('itcRows').insertAdjacentHTML('beforeend',irw())">+ ADD ROW</button>`;
if(k!=='ITC-03')h+=`<label><input type="checkbox" id="i_ca"> Certificate of a Chartered / Cost Accountant attached ${k==='ITC-01'?'(mandatory if claim exceeds ₹2 lakh, Rule 40(1)(d))':'(mandatory, Rule 41(1))'}</label>`;
h+=`<p class="err" id="i_e"></p><button class="btn" onclick="itcSave('${k}')">SAVE</button> <button class="btn s" id="i_sub" onclick="itcSubmit('${k}')">SUBMIT WITH EVC</button></div>`;$('itcF').innerHTML=h;
Object.entries(sv).forEach(([id,v])=>{if(id!=='rows'&&$(id))$(id)[$(id).type==='checkbox'?'checked':'value']=v})}
function itcSave(k){const data={};document.querySelectorAll('#itcF input[id],#itcF select[id]').forEach(e=>data[e.id]=e.type==='checkbox'?e.checked:e.value);if($('itcRows'))data.rows=itcRows();const l=get('saved',[]);l.push({form:k,date:today(),data});put('saved',l);alert(k+' saved. Find it under User Services › My Saved Applications.')}
function itcSubmit(k){const E=[],dd=(a,b)=>Math.floor((new Date(a)-new Date(b))/864e5),tot=zero();let rows=[];
if($('itcRows')){rows=itcRows().filter(r=>r.val>0);if(!rows.length)E.push('Enter at least one row with value');rows.forEach(r=>H.forEach(h=>tot[h]+=r[h]))}
if(k==='ITC-01'){const d=$('i1_dt').value;if(!d)E.push('Enter the eligibility date');else{if(dd(today(),d)>30)E.push('ITC-01 must be filed within 30 days of becoming eligible (Rule 40(1)(b)).');rows.forEach(r=>{if(r.date&&dd(d,r.date)>365)E.push('Invoice '+r.no+' is more than one year old from the eligibility date - not allowed u/s 18(2).')})}if(tsum(tot)>200000&&!$('i_ca').checked)E.push('Claim exceeds ₹2 lakh: CA/CMA certificate is mandatory.')}
if(k==='ITC-02'||k==='ITC-02A'){const g=$('i2_g').value,bal=credBal();if(!validGSTIN(g)||g===G)E.push('Enter a valid transferee GSTIN (other than your own)');if(k==='ITC-02A'&&g&&(g.slice(2,12)!==G.slice(2,12)||g.slice(0,2)!==G.slice(0,2)))E.push('ITC-02A: transferee must have the same PAN and be in the same State');
if(k==='ITC-02A'){const d=$('i2_dt').value;if(!d||dd(today(),d)>30)E.push('ITC-02A must be filed within 30 days of obtaining the new registration (Rule 41A)')}H.forEach(h=>{tot[h]=+$('i2_'+h).value||0;if(tot[h]>bal[h]+0.001)E.push(HN[h]+' exceeds credit ledger balance')});if(!tsum(tot))E.push('Enter the amount to transfer');if(!$('i_ca').checked)E.push('CA/CMA certificate is mandatory')}
if(k==='ITC-03'){const d=$('i3_dt').value;if(!d)E.push('Enter date of event');else if(dd(today(),d)>60)E.push('ITC-03 is to be filed within 60 days of the event (Rule 44(4))');const bal=credBal();if(H.some(h=>tot[h]>bal[h]+0.001))E.push('Credit ledger balance is insufficient - deposit cash via challan and pay through DRC-03 (practice: reduce the amount)')}
if(E.length){$('i_e').innerHTML=E.join('<br>');return}if(!evc(k))return;const arn=arnOf('AA');
if(k==='ITC-01'){addCred('ITC-01 claim u/s 18(1) - ARN '+arn,tot);addApp({kind:'itc',type:'ITC-01 (claim of ITC)',arn,date:today(),status:'Filed - credited to electronic credit ledger'})}
if(k==='ITC-03'){const n={};H.forEach(h=>n[h]=-tot[h]);addCred('ITC-03 reversal - ARN '+arn,n);addApp({kind:'itc',type:'ITC-03 (reversal of ITC)',arn,date:today(),status:'Filed - debited from electronic credit ledger'})}
if(k==='ITC-02'||k==='ITC-02A'){const n={};H.forEach(h=>n[h]=-tot[h]);addCred(k+' transfer to '+$('i2_g').value+' - ARN '+arn,n);addApp({kind:'itc',type:k+' (transfer of ITC to '+$('i2_g').value+')',arn,date:today(),status:'Pending for acceptance by transferee'})}
alert(k+' filed successfully. ARN '+arn);show('ITC Forms')}
/* ---------- menus ---------- */
const US5=['My Saved Applications','View / Download Certificates','View Notices and Orders','View Additional Notices / Orders','My Applications','Search HSN/SAC','Holiday List','Grievance / Complaint','Feedback','Locate GST Practitioner (GSTP)','Engage / Disengage GST Practitioner (GSTP)','Contacts','ITC Forms','Furnish Letter of Undertaking (LUT)','GST Calculator','Invoice Generator','Downloads (Offline Tools)','Practice Tasks'];
(function(){const r=MENU.find(m=>m[0]==='Returns');if(r)r[1].splice(r[1].indexOf('GSTR-2A / 2B')+1,0,'GSTR-2A','GSTR-2B','Invoice Management System (IMS)');const u=MENU.find(m=>m[0]==='User Services');if(u)u[1]=US5;
if($('menu'))$('menu').innerHTML=MENU.map(([g,items])=>items?`<h5>${g}</h5>`+items.map(i=>`<button onclick="show('${i}')">${i}</button>`).join(''):`<button onclick="show('${g}')">${g}</button>`).join('');
const h0=decodeURIComponent(location.hash.slice(1));if(h0&&V[h0]&&CUR!==h0)show(h0)})();
